-- Source 72 was a slash-labelled, conflated source: a static supine tuck hold
-- and a dynamic supine tuck rock differ in base, ordered action, count unit,
-- contact path, fatigue, and stop rules.  Retain all source lineage, archive
-- the underspecified source skeleton, and create two review-only candidates.
-- This migration intentionally creates no approvals and no media verification.
DO $source_72_split$
DECLARE
  migration_key CONSTANT TEXT := '557_coaching_tuck_hold_rock_source_72_identity_split';
  research_version CONSTANT TEXT := '2026-08-10.118';
  source_definition UUID;
  source_variant UUID;
  static_definition CONSTANT UUID := '76dcd5a6-7f4b-4b76-a97d-d80e9c9afee5';
