  rock_variant CONSTANT UUID := 'afcdfdda-b18b-4ee8-9f0c-ec5cf1a47cb6';
  static_card JSONB;
  rock_card JSONB;
BEGIN
  SELECT id INTO source_definition
  FROM coaching.exercise_definition_v1
  WHERE facility_id=1 AND legacy_exercise_id=72 AND slug='tuck-hold-rock';
  SELECT id INTO source_variant
  FROM coaching.exercise_variant_v1
  WHERE definition_id=source_definition AND variant_key='baseline';

  IF source_definition IS NULL OR source_variant IS NULL
    OR NOT EXISTS (SELECT 1 FROM coaching.exercise WHERE id=72 AND facility_id=1)
    OR NOT EXISTS (SELECT 1 FROM coaching.exercise_definition_source_v1
      WHERE definition_id=source_definition AND legacy_exercise_id=72)
    OR NOT EXISTS (SELECT 1 FROM coaching.exercise_score_v1 WHERE exercise_id=72)
    OR NOT EXISTS (SELECT 1 FROM coaching.exercise_difficulty_profile WHERE exercise_id=72)
    OR NOT EXISTS (SELECT 1 FROM coaching.exercise_safety_profile WHERE exercise_id=72) THEN
    RAISE EXCEPTION '% prerequisite Source 72 rows are missing', migration_key;
  END IF;
  IF EXISTS (SELECT 1 FROM coaching.exercise_definition_v1
      WHERE facility_id=1 AND legacy_exercise_id=72
        AND slug IN ('static-supine-tuck-hold','dynamic-supine-tuck-rock')
        AND id NOT IN (static_definition,rock_definition)) THEN
    RAISE EXCEPTION '% target slugs already belong to another definition', migration_key;
  END IF;
  IF EXISTS (SELECT 1 FROM coaching.exercise_definition_v1
      WHERE id=source_definition AND (status IN ('published','deprecated')
        OR reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL))
    OR EXISTS (SELECT 1 FROM coaching.exercise_section_evidence_v1
      WHERE definition_id=source_definition
        AND (reviewer_user_id IS NOT NULL OR review_status NOT IN ('candidate','superseded')))
    OR EXISTS (SELECT 1 FROM coaching.exercise_media_candidate_v1
      WHERE definition_id=source_definition
        AND (reviewer_user_id IS NOT NULL OR reviewed_at IS NOT NULL
          OR review_status NOT IN ('candidate','superseded')))
    OR EXISTS (SELECT 1 FROM coaching.exercise_card_review_v1 WHERE definition_id=source_definition)
    OR EXISTS (SELECT 1 FROM coaching.exercise_card_revision_v1 WHERE definition_id=source_definition) THEN
    RAISE EXCEPTION '% refuses to replace human-reviewed Source 72 content', migration_key;
  END IF;

  -- Seed each descendant's traceable source skeleton before the standard
  -- candidate materializer fills every canonical section. Migration 556 permits
  -- the shared, conflated legacy ID on these review-only descendants.
  INSERT INTO coaching.exercise_definition_v1(
    id,facility_id,legacy_exercise_id,slug,canonical_name,display_name,
    description,family_key,status,content_confidence,scoring_confidence,media_confidence)
  VALUES
    (static_definition,1,72,'static-supine-tuck-hold','Static Supine Tuck Hold','Static Supine Tuck Hold',
      'Seed row replaced by a complete candidate contract in the same migration.','supine_tuck_shape_hold','review',40,40,20),
    (rock_definition,1,72,'dynamic-supine-tuck-rock','Dynamic Supine Tuck Rock','Dynamic Supine Tuck Rock',
      'Seed row replaced by a complete candidate contract in the same migration.','supine_tuck_rock','review',40,40,20)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO coaching.exercise_definition_source_v1(
    definition_id,legacy_exercise_id,source_kind,provenance_json)
  VALUES
    (static_definition,72,'legacy_migration',jsonb_build_object('migration',migration_key,'sourceDisposition','conflated_source_split','humanReviewRequired',TRUE)),
    (rock_definition,72,'legacy_migration',jsonb_build_object('migration',migration_key,'sourceDisposition','conflated_source_split','humanReviewRequired',TRUE))
