    (rock_variant,rock_definition,'supine-shins-wrapped-backward-forward-tuck-rock','Dynamic Supine Tuck Rock Candidate Seed','review')
  ON CONFLICT (id) DO NOTHING;

  UPDATE coaching.exercise_delivery_profile_v1 SET status='archived',updated_at=now()
  WHERE variant_id=source_variant AND status IN ('draft','review');
  UPDATE coaching.exercise_variant_v1 SET
