      'replacementDefinitionIds',jsonb_build_array(static_definition,rock_definition),
      'humanReviewRequired',TRUE,'approvalsCreated',FALSE,'publicationQuarantined',TRUE),updated_at=now()
  WHERE id=source_definition;

  static_card := $static_card${
