    "definition":{"facilityId":1,"legacyExerciseId":72,"preserveLegacyExerciseId":true,"id":"d03d6639-6b4b-469c-8483-ea855be11bca","slug":"dynamic-supine-tuck-rock","canonicalName":"Dynamic Supine Tuck Rock","displayName":"Dynamic Supine Tuck Rock","aliases":["Supine Tuck Rock","Tuck Rock","Back-and-Forth Tuck Rock"],"description":"Start supine on a clean stable mat or floor with both knees drawn toward the chest and hands wrapping the shins. Rock backward and then forward as one compact rounded shape, using controlled back contact only, and return to the same supine tuck start without standing, hand push-off, or head/neck loading. One backward-and-forward return is one repetition. Pause and reset between repetitions. Range, pace, repetitions, surface, rest, direction cueing, and hand grip are delivery annotations. Static tuck holds, seated rocks, tuck-ups, rock-and-roll-to-stand, forward/backward/shoulder rolls, loaded work, assessments, and clinical interventions are different tasks requiring their own reviewed card or variant.","familyKey":"supine_tuck_rock","schemaVersion":"2.0.0","cardVersion":2,"identityContract":"supine_bilateral_knees_to_chest_hands_wrapping_shins_controlled_backward_forward_compact_tuck_rock_returning_to_same_supine_start_without_hand_push_off_or_head_neck_loading","confidence":{"content":76,"scoring":48,"media":30},"movementPatterns":["brace","rotate"],"bodyRegions":["core","spine","thoracic_spine","pelvis","hip","knee","neck"],"requiredEquipment":[],"optionalEquipment":["mat_optional"],"environment":{"surface":"clean stable level mat or floor","space":"one clear longitudinal rocking station with an unobstructed exit","stationCapacity":1,"inspection":["surface condition and traction","clear rock path and exit","communication and coach sightline"],"changeRule":"Changing base, contact path, range, pace, repetitions, hand support, stand-up, load, intent, symptoms, or substitution requires revalidation."},"population":{"exerciseCardDoesNotClas